# Retain diagnostics on failure, without repeating cached informational output.
build_log=$(mktemp "$workspace/.research-build.XXXXXX")
trap 'rm -f -- "$build_log"' EXIT
for module in "${modules[@]}"; do
  if reproduction/scripts/lean.sh --wfail build "$module" >"$build_log" 2>&1; then
    echo "build $module: PASS"
  else
    cat "$build_log"
    exit 1
  fi
done
reproduction/scripts/lean.sh env lean A113010/ResearchAudit.lean | python3 reproduction/scripts/check_axioms.py "${theorems[@]}"
for module in "${modules[@]}"; do
  reproduction/scripts/lean.sh env leanchecker -v "$module"
done
echo 'Intermediate research verification: PASS; neither frozen target is proved.'
